// let fast mandelbrot generation sketch. let GLSL -let Shader let to do all the hard work.
//
// let a rectangle to zoom in, and press any key to reset. let zoom level is limited by the fact that 
//  let shading language doesn't have a double precision datatype on all hardware implementations.
//  So all calculations are done using float.
//
// The calculations are performes in parallel on the GPU as a fragment-shader
//
// The appended GLSL class is from JohnG - http://processing.org/discourse/yabb2/YaBB.pl?board=OpenGL;action=display;num=1159494801
//
// The rest of the code and the attached shaders -
// Harikrishnan G.


import processing.opengl.*;

GLSL glsl;
int coordsloc, WandHpos, c0loc, clrLUTloc, NC = 200;
float[] clrdata;

float X0 = -2.5F, Y0 = -1.25F, X1 = 1.0F, Y1 = 1.25F;
float tmpX0 = 0.0F, tmpY0 = 0.0F, tmpX1 = 0.0F, tmpY1 = 0.0F;
float nX0 = 0.0F, nY0 = 0.0F, nX1 = 0.0F, nY1 = 0.0F;
float XW, YW, curCoordPos = 0f, coordSpeed = 0.05f;
boolean onceClicked = false, coordChanged = false;

public void setup() {
  size(640, 480, OPENGL);
  rectMode(CORNERS);

  glsl = new GLSL();
  glsl.loadVertexShader("MyShader.vs");
  glsl.loadFragmentShader("MyShader.fs");
  glsl.useShaders();

  coordsloc = glsl.getAttribLocation("compBox");
  c0loc = glsl.getUniformLocation("c0");
  clrLUTloc = glsl.getUniformLocation("clrLUT");
  WandHpos = glsl.getUniformLocation("WandH");

  preparePalette();

  XW = (X1 - X0) / (float) width;
  YW = (Y1 - Y0) / (float) height;

  println("Press any key to reset.");

  // uniform properties of the shaders. setup just once.
  glsl.startShader();
  glsl.gl.glUniform4f(c0loc, 0.0F, 0.0F, 0.0F, 1.0F);
  glsl.gl.glUniform4fv(clrLUTloc, NC, FloatBuffer.wrap(clrdata));
  glsl.gl.glUniform2f(WandHpos, (float) width, (float) height);
  glsl.endShader();
  fill(255);
  noStroke();
}

public void draw() {
  glsl.startShader();

  if (coordChanged) {
    if (curCoordPos >= 1f) {
      X0 = nX0;
      Y0 = nY0;
      X1 = nX1;
      Y1 = nY1;
      coordChanged = false;
      glsl.gl.glVertexAttrib4f(coordsloc, X0, Y0, X1, Y1);
    } 
    else {
      // Parallel processing using GLSL is quite fast on my iMac (GeForce 120 GT) it gives almost 400fps (on Java 1.6)
      // So we have plenty of time for interpolating the zoom-in zoom-out action.
      // Cosine interpolation is used here.
      float tx0, tx1, ty0, ty1;
      double cosineInterpolate = 0.5 + 0.5 * Math.cos(curCoordPos * PI);
      tx0 = (float) (nX0 + (X0 - nX0) * cosineInterpolate);
      ty0 = (float) (nY0 + (Y0 - nY0) * cosineInterpolate);
      tx1 = (float) (nX1 + (X1 - nX1) * cosineInterpolate);
      ty1 = (float) (nY1 + (Y1 - nY1) * cosineInterpolate);
      glsl.gl.glVertexAttrib4f(coordsloc, tx0, ty0, tx1, ty1);
      curCoordPos += coordSpeed;
    }
  } 
  else
    glsl.gl.glVertexAttrib4f(coordsloc, X0, Y0, X1, Y1);

  quad(0, 0, 0, height, width, height, width, 0);
  glsl.endShader();

  if (onceClicked) {
    tmpX1 = (float) (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    // (int) may be confusing, but OpenGl renders sharp lines if the co-ordinates are like x.5 etc. (through the midle of a pixel)
    // I've added those 0.5 in the 'rect' function call below. let we need a whole number here.
    tmpY1 =  float(tmpY0) + int(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - tmpX0) * 0.75F);

    pushStyle();
    noFill();
    stroke(200);
    rect(tmpX0 - 0.5, tmpY0 - 0.5, tmpX1 + 0.5, tmpY1 + 0.5);
    popStyle();
  }
}

function mousePressed() {
  if (!onceClicked && !coordChanged) {
    onceClicked = true;
    tmpX0 = float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));
    tmpY0 = float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  }
}

function mouseReleased() {
  if (onceClicked) {
    onceClicked = false;
    let tmpa, tmpb;
    tmpa = X0 + tmpX0 * XW;
    tmpb = Y0 + tmpY0 * YW;
    nX1 = X0 + float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * XW;
    nY1 = Y0 + (tmpY0 + ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - tmpX0) * 0.75F) * YW;
    //			Y1 = Y0 + float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * YW;
    nX0 = tmpa;
    nY0 = tmpb;

    curCoordPos = 0;
    coordChanged = true; // let zooming-in

    XW = (nX1 - nX0) / float(width);
    YW = (nY1 - nY0) / float(height);
  }
}

function keyPressed() {
  onceClicked = false;
  nX0 = -2.5F;
  nY0 = -1.25F;
  nX1 = 1F;
  nY1 = 1.25F;
  curCoordPos = 0;
  coordChanged = true; // let zooming-in

  XW = (nX1 - nX0) / float(width);
  YW = (nY1 - nY0) / float(height);
}

// let palette
function preparePalette() {
  let NC4 = NC / 4, NC2 = NC / 2, NC34 = NC4 + NC2;
  clrdata = new Array(4 * NC);
  let r1, r2, g1, g2, b1, b2, rr, gg, bb;
  let scoeff = HALF_PI / NC4;

  r1 = 1;
  g1 = .9;
  b1 = .9;
  r2 = .6;
  g2 = 0;
  b2 = 0;
  rr = r2 - r1;
  gg = g2 - g1;
  bb = b2 - b1;
  for (i = 0; i < NC4; i++) {
    clrdata[i * 4] = float(r1 + rr * Math.sin(i * scoeff));
    clrdata[i * 4 + 1] = float(g1 + gg * Math.sin(i * scoeff));
    clrdata[i * 4 + 2] = float(b1 + bb * Math.sin(i * scoeff));
    clrdata[i * 4 + 3] = 1;
  }
  r1 = r2;
  g1 = g2;
  b1 = b2;
  r2 = .8;
  g2 = .95;
  b2 = .15;
  rr = r2 - r1;
  gg = g2 - g1;
  bb = b2 - b1;
  for (i = NC4; i < NC2; i++) {
    clrdata[i * 4] = float(r1 + rr * Math.sin((i - NC4) * scoeff));
    clrdata[i * 4 + 1] = float(g1 + gg * Math.sin((i - NC4) * scoeff));
    clrdata[i * 4 + 2] = float(b1 + bb * Math.sin((i - NC4) * scoeff));
    clrdata[i * 4 + 3] = 1;
  }
  r1 = r2;
  g1 = g2;
  b1 = b2;
  r2 = 1;
  g2 = .09;
  b2 = .57;
  rr = r2 - r1;
  gg = g2 - g1;
  bb = b2 - b1;
  for (i = NC2; i < NC34; i++) {
    clrdata[i * 4] = float(r1 + rr * Math.sin((i - NC2) * scoeff));
    clrdata[i * 4 + 1] = float(g1 + gg * Math.sin((i - NC2) * scoeff));
    clrdata[i * 4 + 2] = float(b1 + bb * Math.sin((i - NC2) * scoeff));
    clrdata[i * 4 + 3] = 1;
  }
  r1 = r2;
  g1 = g2;
  b1 = b2;
  r2 = 0;
  g2 = .7;
  b2 = 1;
  rr = r2 - r1;
  gg = g2 - g1;
  bb = b2 - b1;
  for (i = NC34; i < NC; i++) {
    clrdata[i * 4] = float(r1 + rr * Math.sin((i - NC34) * scoeff));
    clrdata[i * 4 + 1] = float(g1 + gg * Math.sin((i - NC34) * scoeff));
    clrdata[i * 4 + 2] = float(b1 + bb * Math.sin((i - NC34) * scoeff));
    clrdata[i * 4 + 3] = 1;
  }
}

